initializePlatformPreferences();
const $ = (id) => document.getElementById(id);
const esc = (value) => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number = v => typeof v === 'number' && Number.isFinite(v);
const price = v => number(v) ? v.toLocaleString('en-IN', {minimumFractionDigits:2,maximumFractionDigits:2}) : '—';
const integer = v => number(v) ? v.toLocaleString('en-IN') : '—';
const tone = v => !number(v) || v === 0 ? 'neutral' : v > 0 ? 'positive' : 'negative';
const percent = v => !number(v) ? '—' : `${v > 0 ? '▲ +' : v < 0 ? '▼ ' : ''}${v.toFixed(2)}%`;
const change = v => `<span class="${tone(v)}">${percent(v)}</span>`;
const date = value => { if (!value) return null; const raw = String(value); const d = new Date(/^\d{4}-\d\d-\d\d[ T]\d\d:\d\d:\d\d$/.test(raw) ? raw.replace(' ','T') + '+05:30' : raw); return Number.isNaN(d.getTime()) ? null : d; };
const stamp = v => date(v) ? date(v).toLocaleString('en-IN',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}) + ' IST' : 'Unavailable';
const timeOnly = v => date(v)?.toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}) || '—';
const state = {groups:[],quotes:{rows:[],market:{},top_performers:[]},rows:new Map(),filter:'all',query:'',sector:'',sort:'match_priority',direction:-1,page:1,size:25,min:null,max:null,refreshing:false,watchlist:[],chart:[],ai:null,settings:null,history:[],historySymbol:'',feed:'Connecting',tickerPaused:false};
let stream, pollTimer, toastTimer, aiTimer, lastChartAsOf, lastFeedMessage=Date.now();
try{document.documentElement.dataset.density=['compact','comfortable','large'].includes(localStorage.getItem('divine-density'))?localStorage.getItem('divine-density'):'comfortable';}catch{document.documentElement.dataset.density='comfortable';}
$('displayDensity').value=document.documentElement.dataset.density;
$('displayDensity').addEventListener('change',event=>{document.documentElement.dataset.density=event.target.value;try{localStorage.setItem('divine-density',event.target.value);}catch{notice('Display updated for this visit. Local preference storage is unavailable.');}});
const headerObserver=new ResizeObserver(entries=>document.documentElement.style.setProperty('--header-height',`${Math.ceil(entries[0].target.getBoundingClientRect().height)}px`));
headerObserver.observe(document.querySelector('.topbar'));
const uniqueStocks = () => [...new Map(state.groups.flatMap(g=>g.stocks).map(s=>[s[0],s])).values()];
const groupName = g => g.id === 'realty' ? 'Realty' : g.id === 'nifty-top-liquid' ? 'NIFTY Top Liquid Stocks (F&O)' : g.name;
const art = (g, eager=false) => `<img class="sector-art" src="/static/sectors/${esc(g.id)}.webp" width="96" height="96" alt="${esc(groupName(g))} illustration" loading="${eager?'eager':'lazy'}" decoding="async">`;
const metric = (label,value,note='',className='',filter=null) => {
  const direction=label.startsWith('BULLISH')?'positive':label.startsWith('BEARISH')?'negative':null;
  const arrow=direction?`<span class="market-heading-arrow ${direction}" aria-hidden="true">${direction==='positive'?'▲':'▼'}</span>`:'';
  const content=`<span>${arrow}${label}</span><strong>${value}</strong><small>${note}</small>`;
  return filter?`<a class="stat-card stat-link ${className}" href="/scanner?filter=${filter}" data-route data-scanner-card="${filter}" aria-label="${esc(SCANNER_FILTERS[filter])}: ${value}. View stocks.">${content}<span class="stat-direction" aria-hidden="true">↗</span></a>`:`<article class="stat-card ${className}">${content}</article>`;
};
function notice(message,error=false,link=null){ const node=$('toast');node.textContent=message;if(link){const anchor=document.createElement('a');anchor.href=link.href;anchor.textContent=link.label;anchor.className='secondary';node.append(document.createTextNode(' '),anchor);}node.className='toast'+(error?' error':'');node.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>node.hidden=true,error?15000:7000); }
async function api(path,options={}){return adminRequest(path,options);}
async function action(button,fn){const text=button.textContent;button.disabled=true;button.textContent='Working…';try{await fn();}catch(e){notice(e.message,true,e.action);}finally{button.disabled=false;button.textContent=text;}}
function stockRows(group){return group.stocks.map(([symbol,name,note,status],index)=>{
  const key=`NSE:${symbol}`,row=state.rows.get(key)||{},resolution=state.quotes.instrument_resolutions?.[key]||{};
  return {...row,symbol:key,name,note:[note,row.resolution_note||resolution.resolution_note].filter(Boolean).join(' '),knownStatus:status,entry:index,quote_symbol:row.quote_symbol||resolution.quote_symbol||key,instrumentStatus:state.quotes.instrument_status?.[key],sector_ids:[group.id],sectors:[groupName(group)],sector:groupName(group),gap_pct:state.quotes.intelligence?.opening?.[key]?.gap_pct??null};
});}
function stats(rows){const unique=[...new Map(rows.map(r=>[r.symbol,r])).values()],symbols=new Set(unique.map(r=>r.symbol));const group=state.groups.find(g=>{const expected=new Set(g.stocks.map(s=>'NSE:'+s[0]));return symbols.size===expected.size&&[...symbols].every(s=>expected.has(s));});const shared=group?state.quotes.intelligence?.sectors.find(s=>s.id===group.id):symbols.size===state.quotes.rows.length?state.quotes.intelligence?.summary:null;const valid=unique.filter(r=>number(r.change_pct)&&number(r.ltp)&&r.ltp>0);return {total:shared?.total??unique.length,available:shared?.available??valid.length,average:shared?.average??(unique.length===1?unique[0].change_pct:null),bull:shared?.advancing??valid.filter(r=>r.change_pct>0).length,bear:shared?.declining??valid.filter(r=>r.change_pct<0).length,exact:shared?.exact??unique.filter(r=>r.match).length,near:shared?.near??unique.filter(r=>r.near_match).length,live:shared?.live??valid.filter(r=>r.quote_status==='live').length,stale:shared?.stale??valid.filter(r=>r.quote_status==='stale').length};}
function sectorCards(){return state.groups.map((g,i)=>{const s=stats(stockRows(g));const status=s.live?`${s.live}/${s.total} live`:s.stale?'Stale quotes':s.available?(state.quotes.market.is_open?'Timestamp unknown':'Market closed'):'Awaiting quotes';return `<a class="sector-card" href="/sectors/${esc(g.id)}" data-route aria-label="View ${esc(groupName(g))}"><div class="sector-card-top">${art(g)}<span class="sector-no">${String(i+1).padStart(2,'0')} / 16</span></div><h3>${esc(groupName(g))}</h3><div class="sector-number"><strong class="${tone(s.average)}">${percent(s.average)}</strong><small>${g.stocks.length} configured entries</small></div><div class="breadth-bar" aria-hidden="true"><span style="width:${s.bull/Math.max(1,s.total)*100}%"></span><span style="width:${s.bear/Math.max(1,s.total)*100}%"></span></div><div class="sector-counts"><span class="positive">▲ ${s.available?s.bull:'—'} Bullish</span><span class="negative">▼ ${s.available?s.bear:'—'} Bearish</span><span class="neutral">${s.available}/${s.total} quotes</span></div><div class="sector-card-bottom"><small><span class="dot ${s.live?'live':''}"></span>${status}</small><span>View Sector ↗</span></div></a>`;}).join('');}
function summary(){const rows=uniqueScannerRows(state.groups,state.quotes),counts=scannerCounts(rows),memberships=state.groups.reduce((n,g)=>n+g.stocks.length,0),available=rows.filter(r=>number(r.ltp)&&r.ltp>0).length,stale=rows.filter(r=>r.quote_status==='stale').length;return metric('TOTAL STOCKS',counts.all,`${memberships} memberships · ${state.groups.length} sectors`,'cyan','all')+metric('EXACT MATCHES',counts.exact,'Previous close = today open','cyan','exact')+metric('NEAR MATCHES',counts.near,`${number(state.quotes.max_difference)?`Within ₹${state.quotes.max_difference}`:'Configured tolerance'} · excludes exact`,'gold','near')+metric('MATCHED STOCKS',counts.matched,'Exact + near · unique stocks','cyan','matched')+metric('BULLISH STOCKS',counts.bull,'▲ Last price above previous close','green','bull')+metric('BEARISH STOCKS',counts.bear,'▼ Last price below previous close','red','bear')+metric('VERIFIED LIVE',counts.live,`${available} prices available · ${stale} stale`,'cyan','live');}
function sectorSection(){return `<section aria-labelledby="sectorsTitle"><div class="section-heading"><div><p class="kicker">THE BIG PICTURE</p><h2 id="sectorsTitle">Explore the market. Sector by sector.</h2><p>16 approved categories. 160 configured entries. One connected view.</p></div><div class="heading-actions"><span class="tiny-badge">◈ NSE EQUITIES</span><a class="secondary" href="/sectors" data-route>All sectors ↗</a></div></div><div class="sector-grid" id="sectorGrid">${sectorCards()}</div><p class="subtle-note">Sector averages and breadth use available unique stocks. Requested duplicate entries and suspended securities stay in their original sectors. ${state.groups.length?148:0} unique configured symbols; 147 scan candidates.</p></section>`;}
function hero(){return `<section class="hero compact-market-hero"><div><h1>Market overview</h1><p class="hero-subtitle">DIVINE CODE 369</p></div><div class="hero-buttons"><button class="primary" data-action="scan">↻ Run opening scan</button><a class="secondary" href="/ai-predictions" data-route>AI Predictions ↗</a></div></section>`;}
function chartPanel(){return `<section class="panel"><div class="panel-head"><div><p class="kicker">THE MARKET IN MOTION</p><h2>Live stock movement</h2></div><span class="tiny-badge" id="movementValue">—</span></div><div class="chart-box" id="movementChart"></div><div class="chart-foot"><span>Equal-weight change · available approved stocks</span><span>Since this page opened</span></div></section>`;}
function aiPreview(){return `<section class="panel ai-preview"><div class="panel-head"><div><p class="kicker">RESEARCH. WITH PERSPECTIVE.</p><h2>DIVINE AI · Prediction Lab</h2></div><span class="ai-symbol" aria-hidden="true">✧</span></div><div id="aiPreview"><h3>Evidence before predictions.</h3><p>Prediction unavailable — insufficient validated historical data.</p><span class="tiny-badge">CHRONOLOGICAL VALIDATION</span></div><a href="/ai-predictions" class="secondary" data-route>Open Prediction Lab ↗</a></section>`;}
function scannerPanel(){return `<section class="panel scanner-panel" aria-label="Close and open scanner"><div class="scanner-top"><div class="panel-head"><div><p class="kicker">THE OPENING PRICE RADAR</p><h2 id="scannerCategory">${esc(SCANNER_FILTERS[state.filter])}</h2><p class="panel-description"><strong>Difference = Today Open − Previous Close.</strong> Opening Difference % is the backend opening gap; Change % is daily price movement.</p></div><button class="secondary" data-action="scan">↻ Update quotes</button></div><div class="scanner-context"><a class="ghost" href="/" data-route>← Back to Dashboard</a><span id="categoryCount" role="status" aria-live="polite"></span><span id="scannerLoading" class="scanner-loading" role="status" hidden>Updating quotes…</span></div><div class="notice" id="scannerNotice">Loading verified scanner data…</div><div class="table-tools"><label class="search">Search name or NSE symbol<input id="stockSearch" type="search" placeholder="Search your universe…" value="${esc(state.query)}" autocomplete="off"></label><label>Sector<select id="sectorFilter"><option value="">All sectors</option>${state.groups.map(g=>`<option value="${esc(g.id)}"${state.sector===g.id?' selected':''}>${esc(groupName(g))}</option>`).join('')}</select></label><label>Min |difference|<input id="minDiff" type="number" min="0" step="0.01" placeholder="Any" value="${state.min??''}"></label><label>Max |difference|<input id="maxDiff" type="number" min="0" step="0.01" placeholder="Any" value="${state.max??''}"></label><label>Rows<select id="pageSize">${[10,25,50,160].map(n=>`<option value="${n}"${state.size===n?' selected':''}>${n===160?'All':n}</option>`).join('')}</select></label><button class="ghost" data-action="reset">Clear filters</button><button class="ghost" data-action="match-first">Matches first</button><button class="secondary" data-action="export">Export CSV ↓</button></div><div class="filter-tabs" aria-label="Filter stocks">${Object.entries(SCANNER_FILTERS).map(([id,name])=>`<button data-filter="${id}" class="${state.filter===id?'active':''}" aria-pressed="${state.filter===id}">${id==='all'?'All Stocks':name} <span id="count-${id}"></span></button>`).join('')}</div></div><div class="table-wrap" tabindex="0" aria-label="Scrollable stock results"><table><thead><tr>${[['name','Stock Name'],['symbol','NSE Symbol'],['sector','Sector'],['prev_close','Previous Close'],['open','Today Open'],['difference','Difference'],['gap_pct','Difference %'],['ltp','Last Price'],['change_pct','Change %'],['volume','Volume'],['status','Match Status']].map(([key,label])=>`<th data-column="${key}" aria-sort="none"><button data-sort="${key}">${label} ↕</button></th>`).join('')}</tr></thead><tbody id="stockBody"></tbody></table></div><div class="table-footer"><span id="resultCount"></span><div class="pagination"><button data-action="prev" aria-label="Previous page">‹</button><span id="pageLabel"></span><button data-action="next" aria-label="Next page">›</button></div></div></section>`;}
function pageHeader(kicker,title,description,actionMarkup=''){return `<div class="page-header"><div><p class="kicker">${kicker}</p><h1>${title}</h1><p>${description}</p></div>${actionMarkup}</div>`;}
function currentGroup(){const id=location.pathname.split('/')[2];return state.groups.find(g=>g.id===id);}
function currentRows(){const g=currentGroup();if(location.pathname.startsWith('/sectors/')&&g)return stockRows(g);const rows=uniqueScannerRows(state.groups,state.quotes).map(r=>({...r,sector:r.sectors.join(' · ')}));if(location.pathname.startsWith('/stocks/')){const symbol=decodeURIComponent(location.pathname.split('/')[2]);return rows.filter(r=>r.symbol===`NSE:${symbol}`);}return rows;}
function filteredRows(){return currentRows().filter(r=>{if(!matchesScannerFilter(r,state.filter))return false;if(state.sector&&!r.sector_ids?.includes(state.sector))return false;if(state.query&&!`${r.name} ${r.symbol}`.toLowerCase().includes(state.query.toLowerCase().trim()))return false;if(state.min!==null&&(!number(r.difference)||Math.abs(r.difference)<state.min))return false;if(state.max!==null&&(!number(r.difference)||Math.abs(r.difference)>state.max))return false;return true;}).sort((a,b)=>{if(state.sort==='match_priority')return compareOpeningPriority(a,b);const x=a[state.sort],y=b[state.sort];if(x==null&&y==null)return a.symbol.localeCompare(b.symbol);if(x==null)return 1;if(y==null)return -1;return (typeof x==='string'?x.localeCompare(y):x-y)*state.direction;});}
function matchBadge(r){const label=r.knownStatus==='suspended'?'SUSPENDED':r.instrumentStatus==='unavailable'?'UNAVAILABLE':r.match?'EXACT MATCH':r.near_match?'NEAR MATCH':r.status||'DATA N/A';return `<span class="match-badge ${r.match?'exact':r.near_match?'near':''}">${esc(label)}</span>`;}
function renderTable(){if(!$('stockBody'))return;const filtered=filteredRows();const pages=Math.max(1,Math.ceil(filtered.length/state.size));if(state.page>pages){state.page=pages;writeScannerLocation();}const rows=filtered.slice((state.page-1)*state.size,state.page*state.size);const html=rows.length?rows.map(r=>`<tr data-stock-symbol="${esc(r.symbol)}" class="${r.match?'scanner-exact':r.near_match?'scanner-near':''}"><td><a href="/stocks/${encodeURIComponent(r.symbol.split(':')[1])}" data-route>${esc(r.name)}</a>${r.note?`<small>${esc(r.note)}</small>`:''}</td><td class="symbol">${esc(r.quote_symbol||r.symbol)}${r.quote_symbol&&r.quote_symbol!==r.symbol?`<small class="symbol-resolution">Configured ${esc(r.symbol)} · verified same issuer</small>`:''}</td><td class="stock-sectors">${esc(r.sector||'Unavailable')}</td><td>${price(r.prev_close)}</td><td>${price(r.open)}${r.opening_date?`<small>Session ${esc(r.opening_date)}</small>`:''}</td><td class="difference-cell" data-column="difference">${openingDifference(r)}</td><td>${change(r.gap_pct)}</td><td>${price(r.ltp)}<span class="quote-label">${esc(r.quote_status||'unavailable')} · ${timeOnly(r.quote_timestamp)}</span></td><td>${change(r.change_pct)}</td><td>${integer(r.volume)}</td><td>${matchBadge(r)}</td></tr>`).join(''):`<tr><td colspan="11" class="empty">${state.quotes.rows.length?'No stocks match these filters. Clear filters to see the tracked universe.':'No verified classifications are available yet. Connect Kite or clear filters to see all tracked stocks.'}</td></tr>`;
  if($('stockBody').innerHTML!==html)$('stockBody').innerHTML=html;
  const rowsAll=currentRows(),category=rowsAll.filter(r=>matchesScannerFilter(r,state.filter)),sectorView=location.pathname.startsWith('/sectors/'),counts=scannerCounts(rowsAll);
  $('scannerCategory').textContent=SCANNER_FILTERS[state.filter];$('categoryCount').textContent=`${filtered.length} ${sectorView?'sector entries':'unique stocks'}${filtered.length!==category.length?` of ${category.length} in category`:''}`;
  if($('scannerPageTitle'))$('scannerPageTitle').textContent=SCANNER_FILTERS[state.filter];
  const memberships=state.groups.reduce((n,g)=>n+g.stocks.length,0),available=new Set(rowsAll.filter(r=>number(r.ltp)&&r.ltp>0).map(r=>r.symbol)).size;
  $('resultCount').textContent=`${filtered.length?`${(state.page-1)*state.size+1}–${Math.min(state.page*state.size,filtered.length)} of `:''}${filtered.length} ${sectorView?'sector entries':'unique stocks'} · ${available} prices available${sectorView?'':` · ${memberships} sector memberships`}`;
  $('pageLabel').textContent=`${state.page} / ${pages}`;document.querySelector('[data-action="prev"]').disabled=state.page<=1;document.querySelector('[data-action="next"]').disabled=state.page>=pages;
  for(const id of Object.keys(SCANNER_FILTERS)){$(`count-${id}`).textContent=sectorView?rowsAll.filter(r=>matchesScannerFilter(r,id)).length:counts[id];}
  $('scannerLoading').hidden=!state.refreshing;document.querySelector('.scanner-panel').setAttribute('aria-busy',String(state.refreshing));
  document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===state.filter);b.setAttribute('aria-pressed',String(b.dataset.filter===state.filter));});document.querySelectorAll('th[data-column]').forEach(th=>th.setAttribute('aria-sort',th.dataset.column===state.sort?(state.direction===1?'ascending':'descending'):'none'));
  const snap=state.quotes;const message=snap.error||(!snap.token_configured?'Connect Zerodha Kite to receive actual market data.':!snap.rows.length?'Waiting for verified provider quotes.':'Opening session: '+(snap.opening_date||'unavailable')+' · Last market update '+stamp(snap.as_of)+' · '+marketLabel()+'. Quotes with old timestamps are labeled stale.');$('scannerNotice').textContent=message;$('scannerNotice').className='notice'+(snap.error?' error':'');}
function lineChart(points,label,field='value',isPercent=true){const values=points.map(p=>p[field]);if(points.length<2||!values.every(number))return `<p class="chart-empty">${esc(points.length?'Collecting a second verified data point…':'Waiting for actual market observations. No illustrative prices are shown.')}</p>`;const min=Math.min(...values),max=Math.max(...values),range=max-min||Math.max(.01,Math.abs(max)*.01);const coords=values.map((v,i)=>[38+i/(values.length-1)*632,142-(v-min)/range*114]);const path=coords.map(([x,y],i)=>`${i?'L':'M'}${x.toFixed(2)} ${y.toFixed(2)}`).join(' ');return `<svg viewBox="0 0 700 170" role="img" aria-label="${esc(label)}"><defs><linearGradient id="chartFill" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#00D8FF" stop-opacity=".21"/><stop offset="1" stop-color="#00D8FF" stop-opacity="0"/></linearGradient></defs><path d="${path} L670 156 L38 156Z" fill="url(#chartFill)"/><path d="${path}" fill="none" stroke="#00D8FF" stroke-width="2"/><text x="5" y="22" fill="#8b9cbb" font-size="9">${max.toFixed(2)}${isPercent?'%':''}</text><text x="5" y="155" fill="#8b9cbb" font-size="9">${min.toFixed(2)}${isPercent?'%':''}</text><circle cx="670" cy="${coords.at(-1)[1]}" r="3" fill="#00F0D0"/></svg>`;}
function updateChart(){if(!$('movementChart'))return;$('movementChart').innerHTML=lineChart(state.chart,'Equal-weight percentage change of available approved stocks');const s=stats(state.quotes.rows);$('movementValue').innerHTML=change(s.average);}
function sectorSummary(g){const s=stats(stockRows(g));return metric('AVERAGE CHANGE',change(s.average),'Available unique stocks','cyan')+metric('BULLISH',s.available?s.bull:'—','▲ Current movement','green')+metric('BEARISH',s.available?s.bear:'—','▼ Current movement','red')+metric('EXACT MATCHES',state.quotes.rows.length?s.exact:'—','Official open = previous close','green')+metric('NEAR MATCHES',state.quotes.rows.length?s.near:'—','Excludes exact','gold')+metric('LATEST UPDATE',timeOnly(state.quotes.as_of),`${s.live} live · ${g.stocks.length} configured`,'cyan');}
function renderRoute(){Object.assign(state,scannerLocation(location.search));if(!state.groups.some(g=>g.id===state.sector))state.sector='';document.querySelectorAll('nav [data-route]').forEach(a=>{const active=a.pathname===location.pathname||(a.pathname==='/sectors'&&location.pathname.startsWith('/sectors/'))||(a.pathname==='/ipo'&&location.pathname.startsWith('/ipo/'));a.classList.toggle('active',active);active?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current');});document.querySelectorAll('.mobile-bottom-nav a').forEach(a=>a.classList.toggle('active',a.pathname===location.pathname||(a.pathname==='/ipo'&&location.pathname.startsWith('/ipo/'))||(a.pathname==='/sectors'&&location.pathname.startsWith('/sectors/'))));$('mobileMore')?.setAttribute('aria-expanded','false');$('navigation').classList.remove('open');$('navMore').open=false;$('providerMenu').open=false;$('menuToggle').setAttribute('aria-expanded','false');const path=location.pathname;document.body.dataset.workspace=path==='/ipo'||path.startsWith('/ipo/')?'ipo':'market';let html='';
  if(path==='/'||path==='/dashboard'){html=hero()+`<section class="stats-grid" id="dashboardStats" aria-label="Market summary">${summary()}</section>`+sectorSection()+`<div class="dashboard-scanner">${scannerPanel()}</div><div class="dashboard-bottom">${chartPanel()}${aiPreview()}</div>`;}
  else if(path==='/sectors'){html=pageHeader('YOUR APPROVED MARKET UNIVERSE','Sector intelligence','16 sectors · 160 memberships',`<button class="secondary" data-action="scan">↻ Update quotes</button>`)+sectorSection();}
  else if(path.startsWith('/sectors/')){const g=currentGroup();html=g?`<div class="breadcrumb"><a href="/sectors" data-route>Sectors</a> / ${esc(groupName(g))}</div><div class="page-header"><div class="page-art">${art(g,true)}<div><p class="kicker">SECTOR INTELLIGENCE</p><h1>${esc(groupName(g))}</h1><p>${g.stocks.length} configured entries · ${new Set(g.stocks.map(s=>s[0])).size} unique stocks · NSE equities</p></div></div></div><div class="summary-strip" id="sectorSummary">${sectorSummary(g)}</div>${scannerPanel()}`:pageHeader('404','Sector not found','Choose one of your approved sectors.');}
  else if(path==='/scanner'){html=pageHeader('PRECISION AT THE OPEN',`<span id="scannerPageTitle">${esc(SCANNER_FILTERS[state.filter])}</span>`,'Previous close vs official open · unique tracked stocks')+scannerPanel();}
  else if(path==='/live-market'){html=pageHeader('CONNECTED MARKET INTELLIGENCE','Live market','Shared Kite feed · provider timestamps',`<span class="tiny-badge" id="liveTransport">${esc(state.quotes.transport||'unavailable')}</span>`)+`<section class="stats-grid" id="dashboardStats">${summary()}</section><div class="dashboard-bottom">${chartPanel()}<section class="panel"><p class="kicker">CONNECTION HEALTH</p><h2>Your market feed</h2><div id="connectionDetails"></div></section></div><section class="panel"><div class="panel-head"><h2>Index context</h2><button class="secondary" data-action="indices">Load Kite indices</button></div><div id="indexCards" class="metrics-grid"><p class="subtle-note">Load index quotes on demand. Account permissions apply.</p></div></section><div class="section-heading"><h2>Approved stock universe</h2></div>`+scannerPanel();}
  else if(path==='/ai-predictions'){html=aiPage();}
  else if(path==='/ipo'||path.startsWith('/ipo/')){html=ipoShell();}
  else if(path==='/watchlists'||path==='/alerts'){html=personalShell();}
  else if(path==='/history'){html=historyPage();}
  else if(path==='/settings'){html=settingsPage();}
  else if(path==='/connections'||path==='/health'){html=connectionPage();}
  else if(path.startsWith('/stocks/')){const symbol=decodeURIComponent(path.split('/')[2]);const stock=uniqueStocks().find(s=>s[0]===symbol);html=stock?`<div class="breadcrumb"><a href="/scanner" data-route>Scanner</a> / ${esc(symbol)}</div>${pageHeader('STOCK INTELLIGENCE',esc(stock[1]),esc(stock[2]||'NSE:'+symbol))}<section class="panel"><div class="stock-header"><div><p class="kicker">LATEST AVAILABLE QUOTE</p><strong id="stockPrice" class="stock-price">—</strong></div><div id="stockChange"></div></div><p class="subtle-note" id="stockTime"></p></section><div class="section-heading"><h2>Opening reference</h2></div>${scannerPanel()}<div class="dashboard-bottom"><section class="panel"><p class="kicker">FORECAST · DISTINCT FROM QUOTE</p><h2>DIVINE AI outlook</h2><div id="stockForecast"></div></section><section class="panel"><p class="kicker">HISTORICAL CONTEXT</p><h2>Daily price history</h2><p class="panel-description">Review actual provider OHLCV candles and stored history.</p><a class="secondary" href="/history?symbol=${encodeURIComponent('NSE:'+symbol)}" data-route>View history ↗</a></section></div>`:pageHeader('404','Stock not found','Choose a stock from the approved universe.');}
  else{html=pageHeader('404','Page not found','Return to your market dashboard.',`<a class="secondary" href="/" data-route>Dashboard ↗</a>`);}
  $('main').innerHTML=html;mountIPO({api,notice});mountPersonalPage({notice});mountConnections();mountCommandCenter({groups:state.groups,quotes:state.quotes,api,notice,feed:state.feed});document.title=(path==='/'?'Dashboard':path.startsWith('/sectors/')?groupName(currentGroup()||{name:'Sector'}):path.slice(1).replaceAll('-',' '))+' · DIVINE CODE 369';bindControls();updateDynamic();if(path==='/ai-predictions')loadAI();if(path==='/settings'){loadSettings();mountPlatformSettings(notice);}if(path==='/history'){loadImports();const selected=new URLSearchParams(location.search).get('symbol');if(selected&&[...$('historySymbol').options].some(o=>o.value===selected))$('historySymbol').value=selected;}}
function writeScannerLocation(push=false){const href=location.pathname+scannerSearch(state)+location.hash;if(href!==location.pathname+location.search+location.hash)history[push?'pushState':'replaceState']({},'',href);}
function refreshScanner(push=false){renderTable();writeScannerLocation(push);}
function bindControls(){const search=$('stockSearch');search?.addEventListener('input',()=>{state.query=search.value;state.page=1;refreshScanner();});$('sectorFilter')?.addEventListener('change',e=>{state.sector=e.target.value;state.page=1;refreshScanner();});for(const [id,key]of [['minDiff','min'],['maxDiff','max']])$(id)?.addEventListener('input',e=>{state[key]=e.target.value===''?null:Math.max(0,Number(e.target.value));state.page=1;refreshScanner();});$('pageSize')?.addEventListener('change',e=>{state.size=Number(e.target.value);state.page=1;refreshScanner();});}
function navigate(href){history.pushState({},'',href);renderRoute();window.scrollTo({top:0,behavior:'instant'});$('main').focus({preventScroll:true});}
function updateSummary(){const grid=$('dashboardStats');if(!grid)return;const template=document.createElement('template');template.innerHTML=summary();if(grid.children.length!==template.content.children.length){grid.innerHTML=template.innerHTML;return;}[...template.content.children].forEach((fresh,index)=>{const card=grid.children[index];for(const selector of ['strong','small']){const before=card.querySelector(selector),after=fresh.querySelector(selector);if(before.textContent!==after.textContent)before.textContent=after.textContent;}card.setAttribute('aria-label',fresh.getAttribute('aria-label'));});}
function updateDynamic(){updateSummary();updateSectorGrid();if($('sectorSummary'))$('sectorSummary').innerHTML=sectorSummary(currentGroup());renderTable();updateChart();if($('connectionDetails'))$('connectionDetails').innerHTML=settingRow('Provider transport',esc(state.quotes.transport||'unavailable'))+settingRow('Browser connection',esc(state.feed))+settingRow('Last market fetch',stamp(state.quotes.as_of))+settingRow('Latest provider quote',stamp(latestProviderStamp()))+settingRow('REST fallback interval',`${state.quotes.quote_poll_seconds||10}s during session`)+`<p class="subtle-note">${esc(state.quotes.stream_error||state.quotes.error||'Full-mode subscriptions use the approved instrument tokens only.')}</p>`;if($('liveTransport'))$('liveTransport').textContent=state.quotes.transport||'unavailable';if($('stockPrice')){const symbol='NSE:'+decodeURIComponent(location.pathname.split('/')[2]);const row=state.rows.get(symbol);$('stockPrice').textContent=price(row?.ltp);$('stockChange').innerHTML=change(row?.change_pct);$('stockTime').textContent=`${row?.quote_status||'Unavailable'} · Provider timestamp ${stamp(row?.quote_timestamp)}`;const p=state.ai?.predictions.find(p=>p.symbol===symbol);$('stockForecast').innerHTML=p?`<p>${esc(p.horizon)}</p><p class="positive">▲ Up ${(p.probability_up*100).toFixed(1)}%</p><p class="negative">▼ Down ${(p.probability_down*100).toFixed(1)}%</p><p class="subtle-note">${esc(p.model_name)} · ${esc(p.version)} · ${stamp(p.created_at)} · Based on session ${esc(p.as_of)}. Forecast, not a live price.</p>`:`<p class="subtle-note">Prediction unavailable — insufficient validated historical data.</p>`;}updateAIPreview();}
function latestProviderStamp(){return state.quotes.rows.map(r=>r.quote_timestamp).filter(Boolean).sort().at(-1);}
function updateSectorGrid(){const grid=$('sectorGrid');if(!grid)return;const template=document.createElement('template');template.innerHTML=sectorCards();[...template.content.children].forEach((fresh,index)=>{const card=grid.children[index];if(!card)return;for(const selector of ['.sector-number','.breadth-bar','.sector-counts','.sector-card-bottom']){const before=card.querySelector(selector),after=fresh.querySelector(selector);if(before.innerHTML!==after.innerHTML)before.innerHTML=after.innerHTML;}});}
function applyQuotes(snap){state.quotes=snap;state.rows=new Map(snap.rows.map(r=>[r.symbol,r]));const s=stats(snap.rows);if(number(s.average)&&lastChartAsOf!==snap.as_of){state.chart.push({value:s.average,time:snap.as_of});state.chart=state.chart.slice(-180);lastChartAsOf=snap.as_of;}updateStatus();updateTicker();updateDynamic();updateCommandCenter({groups:state.groups,quotes:state.quotes,api,notice,feed:state.feed});}
function updateStatus(){
  const q=state.quotes,market=q.market||{},available=stats(q.rows),label=marketLabel();
  $('navMarketStatus').textContent=label;$('navMarketStatus').dataset.phase=market.status||'unknown';
  $('tickerMarketStatus').textContent=label;$('tickerMarketStatus').dataset.phase=market.status||'unknown';
  document.querySelector('.ticker').dataset.session=market.status||'unknown';
  $('feedStatus').textContent=`${state.feed} · ${q.transport||'unavailable'} · Quote ${timeOnly(latestProviderStamp())}`;
}
function updateTicker(){const items=(state.quotes.top_performers||[]).filter(r=>number(r.change_pct)&&number(r.ltp));const track=$('tickerTrack');if(!items.length){track.innerHTML='<span class="ticker-empty">Awaiting verified Kite quotes · No sample market data</span>';return;}const html=items.map(r=>`<a class="ticker-stock" href="/stocks/${encodeURIComponent(r.symbol.split(':')[1])}" data-route><strong>${esc(r.symbol.split(':')[1])}</strong><span>₹${price(r.ltp)}</span>${change(r.change_pct)}<small>${esc(r.quote_status)} ${timeOnly(r.quote_timestamp)}</small></a>`).join('');const fresh=`<div class="ticker-set">${html}</div><div class="ticker-set" aria-hidden="true" inert>${html}</div>`;if(track.innerHTML!==fresh)track.innerHTML=fresh;}
async function loadQuotes(){state.refreshing=true;if($('scannerLoading'))$('scannerLoading').hidden=false;try{applyQuotes(await api('/api/quotes'));}catch{state.feed='Server unavailable';updateStatus();updateCommandCenter({groups:state.groups,quotes:state.quotes,api,notice,feed:state.feed});}finally{state.refreshing=false;renderTable();}}
function startFeed(){stream?.close();clearInterval(pollTimer);pollTimer=null;if('EventSource'in window){stream=new EventSource('/api/stream');stream.addEventListener('quotes',event=>{lastFeedMessage=Date.now();try{applyQuotes(JSON.parse(event.data));}catch{notice('A market update could not be read.',true);}});stream.addEventListener('connections',event=>{try{receiveConnections(JSON.parse(event.data),refreshIPOFromBackend);}catch{}});stream.addEventListener('heartbeat',()=>{lastFeedMessage=Date.now();});stream.onopen=()=>{lastFeedMessage=Date.now();state.feed='Connected';clearInterval(pollTimer);pollTimer=null;updateStatus();};stream.onerror=()=>{state.feed='Reconnecting';updateStatus();if(!pollTimer)pollTimer=setInterval(loadQuotes,10000);};}else{state.feed='Browser polling';pollTimer=setInterval(loadQuotes,10000);}}
function settingRow(label,value){return `<div class="setting-row"><span>${label}</span><span>${value}</span></div>`;}
function aiPage(){return `<section class="ai-hero"><div><p class="kicker">FORECASTS ARE ESTIMATES. EVIDENCE MATTERS.</p><h1>DIVINE AI <span>✧</span><br>MARKET PREDICTION LAB</h1><p>Interpretable models. Chronological evaluation. Calibrated probabilities.<br>Forecasts stay separate from actual market quotes.</p></div><div class="ai-actions"><button class="secondary" data-action="predict">Generate forecasts</button><button class="primary" data-action="train">Train & validate ↗</button></div></section><div class="summary-strip" id="aiSummary"></div><div id="aiContent"><div class="empty">Loading model evidence…</div></div>`;}
async function loadAI(){try{state.ai=await api('/api/ai/status');renderAI();updateAIPreview();if($('stockForecast'))updateDynamic();}catch(e){if($('aiContent'))$('aiContent').innerHTML=`<div class="notice error">${esc(e.message)}</div>`;}}
function updateAIPreview(){if(!$('aiPreview')||!state.ai)return;const m=state.ai.model;const count=state.ai.predictions.length;if(m)$('aiPreview').innerHTML=`<h3>${esc(m.name)}</h3><p>${count} forecast${count===1?'':'s'} from validated daily candles. Out-of-sample accuracy: ${((m.metrics.out_of_sample?.directional_accuracy||0)*100).toFixed(1)}%.</p><span class="tiny-badge">FORECAST · ${esc(m.version)}</span>`;}
function predictionTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Stock / model</th><th>Latest quote</th><th>Forecast reference close</th><th>Up probability</th><th>Down probability</th><th>Horizon / data session</th><th>Generated</th></tr></thead><tbody>${rows.map(p=>`<tr><td><a href="/stocks/${encodeURIComponent(p.symbol.split(':')[1])}" data-route>${esc(p.name)}</a><small>${esc(p.symbol)} · ${esc(p.model_name)}<br>${esc(p.version)}</small></td><td>${price(state.rows.get(p.symbol)?.ltp)}<small>${esc(state.rows.get(p.symbol)?.quote_status||'Unavailable')}</small></td><td>${price(p.price)}</td><td class="positive">▲ ${(p.probability_up*100).toFixed(1)}%<div class="prob-track"><span style="width:${p.probability_up*100}%"></span></div></td><td class="negative">▼ ${(p.probability_down*100).toFixed(1)}%</td><td>${esc(p.horizon)}<small>Based on completed session ${esc(p.as_of)} · Return range unsupported</small></td><td>${stamp(p.created_at)}</td></tr>`).join('')}</tbody></table></div>`;}
function renderAI(){if(!$('aiContent')||!state.ai)return;const a=state.ai,m=a.model,e=m?.metrics?.out_of_sample,c=a.coverage;document.querySelectorAll('[data-action="train"],[data-action="predict"]').forEach(b=>b.disabled=a.storage_authorized===false);$('aiSummary').innerHTML=metric('MODEL STATUS',m?'Validated':esc(a.state),'No forecast without validation','cyan')+metric('LAST TRAINING',m?timeOnly(m.trained_at):'—',m?esc(m.trained_at.slice(0,10)):'Awaiting sufficient data')+metric('DAILY CANDLES',integer(c.candles),`${c.instruments} instruments`)+metric('TEST ACCURACY',e?`${(e.directional_accuracy*100).toFixed(1)}%`:'—','Untouched test period','green')+metric('DATA THROUGH',c.last_date||'—','Completed daily sessions')+metric('FORECAST HORIZON','1 session','Next session open → close','gold');
  let content=`<div class="notice">${esc((a.blockers||[]).join(' '))} ${esc(a.message)} ${m?'Active model '+esc(m.version)+'.':''}</div>`;
  content+=a.predictions.length?`<section class="panel scanner-panel"><div class="scanner-top"><p class="kicker">MODEL FORECASTS · NOT ACTUAL QUOTES</p><h2>Stock outlook</h2><p class="subtle-note">${esc(m?.payload.calibration||'')} Predictions are dated by their input session and can be outdated. No guaranteed trading result.</p></div>${predictionTable(a.predictions)}</section>`:`<section class="ai-empty"><span class="ai-symbol" aria-hidden="true">✧</span><h3>Prediction unavailable — insufficient validated historical data.</h3><p>Import authorized completed candles, then train and validate a model. Forecasts appear only after inference succeeds and the model passes its out-of-sample calibration and baseline checks.</p><a class="secondary" href="/history" data-route>Manage historical data ↗</a></section>`;
  if(e){content+=`<div class="dashboard-bottom"><section class="panel"><p class="kicker">UNTOUCHED OUT-OF-SAMPLE PERIOD</p><h2>Model evidence</h2><p class="subtle-note">${esc(e.start)} to ${esc(e.end)} · ${e.samples} observations · ${e.sessions} sessions. ${esc(m.payload.calibration)}</p><div class="metrics-grid">${[['Precision',e.precision],['Recall',e.recall],['F1 score',e.f1],['ROC-AUC',e.roc_auc],['Brier score',e.brier_score],['Calibration error',e.calibration_error],['Majority baseline',e.majority_class_baseline.directional_accuracy],['Max drawdown',e.maximum_drawdown]].map(([n,v])=>`<div class="metric"><small>${n}</small><strong class="${n==='Max drawdown'?tone(v):''}">${number(v)?v.toFixed(3):'—'}</strong></div>`).join('')}</div><p class="subtle-note">MAE / RMSE and return ranges: unsupported by this direction classifier. ${esc(m.payload.universe_note)}</p></section><section class="panel"><p class="kicker">COSTED RESEARCH STRATEGY</p><h2>Model performance</h2><div class="chart-box">${lineChart(e.equity_curve.map(p=>({value:p.return*100})),'Out-of-sample research equity return after costs')}</div><p class="subtle-note">Return after costs: ${change(e.backtest_return_after_costs*100)} · ${e.round_trip_cost_bps} bps per round trip. ${esc(e.backtest_note)} Cash baseline: 0%.</p><h3>Calibration: forecast vs observed</h3><div class="table-wrap"><table><thead><tr><th>Mean forecast</th><th>Observed up rate</th><th>Samples</th></tr></thead><tbody>${e.calibration_bins.map(b=>`<tr><td>${(b.forecast*100).toFixed(1)}%</td><td>${(b.observed*100).toFixed(1)}%</td><td>${b.count}</td></tr>`).join('')}</tbody></table></div></section></div>`;}
  content+=`<section class="panel" style="margin-top:22px"><p class="kicker">FORECAST AUDIT TRAIL</p><h2>Prediction history · actual versus forecast</h2><div class="table-wrap"><table><thead><tr><th>Symbol</th><th>Input session</th><th>Forecast up</th><th>Actual next-session return</th><th>Result</th><th>Model version</th></tr></thead><tbody>${a.history.length?a.history.map(p=>`<tr><td>${esc(p.symbol)}</td><td>${esc(p.as_of)}</td><td class="positive">▲ ${(p.probability_up*100).toFixed(1)}%</td><td>${number(p.actual_return)?change(p.actual_return*100):'Pending realized session'}</td><td>${number(p.actual_return)?((p.probability_up>=.5)===(p.actual_return>0)?'Correct direction':'Incorrect direction'):'Unresolved'}</td><td>${esc(p.version)}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No prediction history yet.</td></tr>'}</tbody></table></div></section>`;$('aiContent').innerHTML=content;}
function options(){const personal=state.watchlist.filter(s=>!uniqueStocks().some(v=>'NSE:'+v[0]===s));return uniqueStocks().map(([s,n])=>`<option value="NSE:${esc(s)}">${esc(s)} · ${esc(n)}</option>`).join('')+personal.map(s=>`<option value="${esc(s)}">${esc(s)} · Personal watchlist</option>`).join('');}
function historyPage(){return pageHeader('AUTHORIZED RESEARCH DATA','Market history','Explore real provider candles and build resumable research datasets only after explicit storage authorization.')+`<div class="history-grid"><section class="panel"><p class="kicker">DAILY OHLCV</p><h2>Session history</h2><div class="control-row"><label>Stock<select id="historySymbol">${options()}</select></label><button class="secondary" data-action="history">Load 8 sessions</button><button class="ghost" data-action="stored">Stored history</button></div><p class="subtle-note" id="historyNotice">Choose an instrument. Viewing candles does not enable storage.</p><div class="chart-box" id="historyChart"><p class="chart-empty">No historical candles loaded.</p></div><div class="table-wrap"><table><thead><tr><th>Session</th><th>Open</th><th>High</th><th>Low</th><th>Close</th><th>Change %</th><th>Volume</th></tr></thead><tbody id="historyBody"><tr><td colspan="7" class="empty">No historical data loaded.</td></tr></tbody></table></div></section><section class="panel"><p class="kicker">RESUMABLE DATASET BUILDER</p><h2>Import authorized candles</h2><p class="subtle-note">Paid historical access and retention rights are separate. Storage stays disabled until you explicitly authorize historical retention and ML use.</p><div class="form-grid"><label>Candle interval<select id="importInterval"><option value="day">Daily</option><option value="minute">1 minute</option><option value="5minute">5 minutes</option><option value="15minute">15 minutes</option><option value="60minute">60 minutes</option></select></label><label>Calendar days<input id="importDays" type="number" value="365" min="1" max="1825"></label></div><label class="import-options"><input id="importAll" type="checkbox">Import the full approved candidate universe</label><div class="control-row" style="margin-top:18px"><button class="primary" data-action="import">Queue historical backfill ↓</button><button class="secondary" data-action="incremental">Incremental update ↻</button></div><div class="notice" id="importNotice">Checking server authorization…</div><p class="subtle-note">Daily imports use completed sessions only. Jobs save progress after each committed batch. Retrying a batch cannot create duplicate candles. Intraday access requires its own flag.</p><a href="/ai-predictions" class="secondary" data-route>Open Prediction Lab ↗</a></section></div><section class="panel import-progress"><div class="panel-head"><div><p class="kicker">DURABLE IMPORT LOG</p><h2>Import progress</h2></div><button class="secondary" data-action="importStatus">Refresh progress</button></div><div id="importSummary"></div><div id="importJobs"><p class="subtle-note">Loading saved job progress…</p></div></section>`;}
async function loadHistory(stored=false){const symbol=$('historySymbol').value;const data=await api('/api/history/'+encodeURIComponent(symbol)+(stored?'?stored=true':''));state.history=[...(data.data||[])].sort((a,b)=>String(a.timestamp||a.date).localeCompare(String(b.timestamp||b.date)));$('historyNotice').textContent=`${state.history.length} candles · ${symbol} · ${stored?'Stored authorized Kite data':'Kite historical endpoint'} · Historical prices, not live quotes`;$('historyChart').innerHTML=lineChart(state.history.map(b=>({value:b.close})),'Historical closing prices', 'value',false);$('historyBody').innerHTML=state.history.length?state.history.map((b,i)=>`<tr><td>${esc((b.timestamp||b.date).slice(0,10))}</td><td>${price(b.open)}</td><td>${price(b.high)}</td><td>${price(b.low)}</td><td>${price(b.close)}</td><td>${i?change((b.close/state.history[i-1].close-1)*100):'—'}</td><td>${integer(b.volume)}</td></tr>`).reverse().join(''):'<tr><td colspan="7" class="empty">No stored candles for this instrument.</td></tr>';}
function settingsPage(){return pageHeader('YOUR CONNECTED WORKSPACE','Settings & data reliability','Provider capabilities are reported only when verified. Credentials stay in the server environment.')+`<div class="settings-grid"><section class="panel"><p class="kicker">CONNECTION & CAPABILITIES</p><h2>Zerodha Kite</h2><div id="settingsDetails"><p class="subtle-note">Loading server configuration…</p></div><a href="/auth/kite/login" class="secondary">Connect / renew Kite session ↗</a><p class="subtle-note">Daily access tokens remain server-side. A configured token is not proof of current authorization.</p><h3>Administrator session</h3><div id="adminSession" aria-live="polite">Checking administrator session...</div></section><section class="panel"><p class="kicker">PERSONAL WATCHLIST</p><h2>Your watchlist</h2><p class="subtle-note">This separate personal list supports up to 500 exchange-qualified instruments. The scanner's approved 16-sector mapping stays fixed.</p><label for="symbolsInput" class="subtle-note">One NSE:SYMBOL or BSE:SYMBOL per line</label><textarea id="symbolsInput" spellcheck="false" placeholder="NSE:RELIANCE">${esc(state.watchlist.join('\n'))}</textarea><div class="control-row"><button class="primary" data-action="save">Save personal list</button><button class="ghost" data-action="universe">Load 150 optionable equities</button></div><p class="subtle-note">Loading optionable equities replaces only the personal watchlist when you explicitly choose this action.</p></section></div><section class="panel"><p class="kicker">STORAGE & RESEARCH POLICY</p><h2>Data coverage and retention</h2><div id="unifiedHealthSummary"></div><div id="storageDetails"></div></section>${reconciliationPanel()}`;}
async function loadSettings(){mountAdminSession();try{state.settings=await api('/api/settings');loadReconciliation();if(!$('settingsDetails'))return;const s=state.settings;$('settingsDetails').innerHTML=settingRow('Kite token',state.quotes.token_configured?'Configured · authorization unverified':'Not configured')+settingRow('Streaming requested',s.streaming_enabled?'Enabled':'Disabled')+settingRow('Historical access setting',s.historical_enabled?'Enabled · verify capability below':'Disabled')+settingRow('Data retention authorization',s.retention_authorized?'Enabled by server owner':'Not enabled')+settingRow('Exchange calendar',s.market_calendar.calendar_verified?`Official NSE calendar · through ${s.market_calendar.calendar_valid_through||'operator verification'}`:'Unverified · calendar update required')+(s.coverage.capabilities||[]).map(c=>settingRow(esc(c.name),`${esc(c.status)}<small> ${esc(c.detail)}</small>`)).join('')+`<p class="subtle-note">${esc(s.market_depth)}</p>`;$('storageDetails').innerHTML=settingRow('Stored daily candles',`${s.coverage.candles} · ${s.coverage.instruments} instruments`)+settingRow('Historical coverage',`${s.coverage.first_date||'—'} → ${s.coverage.last_date||'—'}`)+settingRow('Aggregated quote snapshots',`${s.coverage.snapshots} · every ${s.snapshot_interval_seconds}s`)+settingRow('Retention',`${s.daily_retention_days} days daily · ${s.intraday_retention_days} days intraday · ${s.snapshot_retention_days} days snapshots`)+settingRow('Scheduled retraining',`${s.auto_retrain_enabled?'Enabled':'Disabled'} · requires ${s.training_min_new_sessions} new sessions`)+`<p class="subtle-note">${esc(s.historical_note)} No incoming raw tick stream is stored.</p>`;}catch(e){notice(e.message,true);}}
function exportRows(){const rows=filteredRows();const columns=[['name','Stock Name'],['symbol','NSE Symbol'],['sector','Sector'],['prev_close','Previous Close'],['open','Today Open'],['difference','Difference'],['gap_pct','Difference %'],['ltp','Last Price'],['change_pct','Change %'],['volume','Volume'],['status','Match Status'],['quote_status','Quote Status'],['quote_timestamp','Provider Timestamp']];const cell=v=>'"'+String(v??'').replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const content='\ufeff'+[columns.map(c=>cell(c[1])).join(','),...rows.map(r=>columns.map(([key])=>cell(r[key])).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='divine-code-369-scanner.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Current filtered results exported.');}
document.addEventListener('click',async event=>{const anchor=event.target.closest('a[data-route]');if(anchor&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&!event.altKey&&event.button===0){event.preventDefault();navigate(anchor.href);return;}const filter=event.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;state.page=1;refreshScanner(true);return;}const sort=event.target.closest('[data-sort]');if(sort){state.direction=state.sort===sort.dataset.sort?-state.direction:1;state.sort=sort.dataset.sort;refreshScanner();return;}const button=event.target.closest('[data-action]');if(!button)return;
  switch(button.dataset.action){case'scan':await action(button,async()=>{await api('/api/scan',{method:'POST'});await loadQuotes();notice('Quote cache updated. Official opening references are preserved.');});break;
  case'match-first':state.sort='match_priority';state.direction=-1;state.page=1;refreshScanner();break;
  case'prev':state.page--;refreshScanner();break;
  case'next':state.page++;refreshScanner();break;
  case'reset':state.filter='all';state.query=state.sector='';state.min=state.max=null;state.page=1;state.sort='match_priority';state.direction=-1;$('stockSearch').value='';$('sectorFilter').value='';$('minDiff').value='';$('maxDiff').value='';refreshScanner(true);break;
  case'export':exportRows();break;case'history':case'stored':await action(button,()=>loadHistory(button.dataset.action==='stored'));break;case'import':case'incremental':await action(button,async()=>{const d=await api('/api/history/import',{method:'POST',body:JSON.stringify({symbol:$('historySymbol').value,all_approved:$('importAll').checked,days:Number($('importDays').value),interval:$('importInterval').value,incremental:button.dataset.action==='incremental'})});notice(`Import ${d.id.slice(0,8)} queued. Progress is persisted in SQLite.`);await loadImports();});break;case'importStatus':await loadImports();break;case'audit':await action(button,async()=>{await api('/api/instruments/reconcile',{method:'POST'});await loadReconciliation();notice('Kite instrument reconciliation refreshed. Approved memberships are unchanged.');});break;case'train':await action(button,async()=>{const d=await api('/api/ai/train',{method:'POST'});notice(d.message);await loadAI();});break;case'predict':await action(button,async()=>{const d=await api('/api/ai/predict',{method:'POST'});notice(`${d.count} forecasts generated.`);await loadAI();});break;case'save':await action(button,async()=>{const d=await api('/api/watchlist',{method:'PUT',body:JSON.stringify({symbols:$('symbolsInput').value})});state.watchlist=d.symbols;$('symbolsInput').value=d.symbols.join('\n');notice(`Saved ${d.count} personal instruments.`);});break;case'universe':await action(button,async()=>{const d=await api('/api/watchlist/universe',{method:'POST'});state.watchlist=d.symbols;$('symbolsInput').value=d.symbols.join('\n');notice(`Loaded ${d.nse_count} NSE and ${d.bse_count} BSE optionable equities into your personal list.`);});break;case'indices':await action(button,async()=>{const d=await api('/api/market-overview');$('indexCards').innerHTML=d.cards.length?d.cards.map(r=>`<div class="metric"><small>${esc(r.symbol)}</small><strong>${price(r.price)}</strong><p>${change(r.change_pct)}</p><small>Provider ${stamp(r.quote_timestamp)}</small><small>Fetched ${stamp(d.as_of)} · on demand</small></div>`).join(''):'<p class="subtle-note">No index quotes returned.</p>';});break;}
});
$('tickerPause').addEventListener('click',()=>{state.tickerPaused=!state.tickerPaused;document.querySelector('.ticker').classList.toggle('paused',state.tickerPaused);$('tickerPause').textContent=state.tickerPaused?'▶':'Ⅱ';$('tickerPause').setAttribute('aria-label',state.tickerPaused?'Resume stock ticker':'Pause stock ticker');$('tickerPause').setAttribute('aria-pressed',String(state.tickerPaused));});
$('menuToggle').addEventListener('click',()=>{const open=$('navigation').classList.toggle('open');$('menuToggle').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',event=>{if(event.key==='Escape'){for(const id of ['navMore','providerMenu']){const menu=$(id),inside=menu.contains(document.activeElement);menu.open=false;if(inside)menu.querySelector('summary').focus();}if($('navigation').classList.contains('open')&&$('navigation').contains(document.activeElement))$('menuToggle').focus();$('navigation').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');}});
$('providerMenu').addEventListener('toggle',()=>{if($('providerMenu').open){$('navigation').classList.remove('open');$('menuToggle').setAttribute('aria-expanded','false');$('navMore').open=false;}});
document.addEventListener('click',event=>{for(const id of ['navMore','providerMenu']){const menu=$(id);if(menu.open&&!menu.contains(event.target))menu.open=false;}});
window.addEventListener('popstate',()=>{state.page=1;renderRoute();});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadQuotes();});
setInterval(()=>{if(stream&&Date.now()-lastFeedMessage>40000&&!document.hidden){stream.close();state.feed='Reconnecting';loadQuotes();lastFeedMessage=Date.now();startFeed();}},10000);
async function initialize(){startISTClock(updateIPOFreshness);initializeConnections(api,notice);if(location.pathname==='/ipo'||location.pathname.startsWith('/ipo/'))renderRoute();try{const [universe,status]=await Promise.all([api('/static/sector-universe.json'),api('/api/status')]);if(universe.groups.length!==16||universe.groups.some(g=>g.stocks.length!==10))throw new Error('Approved universe must contain exactly 16 sectors and 160 entries.');state.groups=universe.groups;state.watchlist=status.watchlist;if(status.connections)receiveConnections(status.connections,refreshIPOFromBackend);applyQuotes(status.market);if(!$('ipoTerminal'))renderRoute();startFeed();loadAI();clearInterval(aiTimer);aiTimer=setInterval(()=>{if(location.pathname==='/ai-predictions')loadAI();},15000);}catch(e){if($('ipoTerminal')){startFeed();notice('The stock workspace is unavailable; IPO Intelligence remains independent.');return;}$('main').innerHTML=`<section class="panel"><h1>Workspace unavailable</h1><p class="notice error">${esc(e.message)}</p><button class="secondary" data-action="retry">Retry connection</button></section>`;document.querySelector('[data-action="retry"]').onclick=initialize;}}
function marketLabel(){const m=state.quotes.market||{};return (m.label||(m.is_open?'NSE · Normal market':'NSE · Market closed'))+(m.calendar_verified?'':' · Calendar unverified');}
function reconciliationPanel(){return `<section class="panel reconciliation"><div class="panel-head"><div><p class="kicker">APPROVED UNIVERSE AUDIT</p><h2>Instrument reconciliation</h2><p class="panel-description">Memberships stay fixed. Same-company aliases are explicit and source-backed.</p></div><div class="control-row"><a class="secondary" href="/api/instruments/reconciliation?download=true">Download full report ↓</a><button class="secondary" data-action="audit">Audit Kite master ↻</button></div></div><div id="reconciliationContent"><p class="subtle-note">Loading verified metadata…</p></div></section>`;}
async function loadReconciliation(){try{const r=await api('/api/instruments/reconciliation');if(!$('reconciliationContent'))return;const rows=r.instruments;const renderRows=items=>items.map(i=>`<tr><td>${esc(i.requested_symbol)}</td><td>${esc(i.provider_symbol||i.candidate_provider_symbol||'--')}</td><td><span class="match-badge ${i.state==='verified'?'exact':''}">${esc(i.state)}</span></td><td>${esc(i.resolution_kind)}</td><td><span class="import-request-note">${esc(i.explanation)}</span></td><td>${stamp(i.checked_at)}</td></tr>`).join('');const table=items=>`<div class="table-wrap"><table><thead><tr><th>Configured instrument</th><th>Verified / candidate quote symbol</th><th>Status</th><th>Resolution</th><th>Evidence note</th><th>Verified at</th></tr></thead><tbody>${renderRows(items)}</tbody></table></div>`;$('reconciliationContent').innerHTML=`<div class="metrics-grid"><div class="metric"><small>Configured entries</small><strong>${r.total_configured_entries}</strong></div><div class="metric"><small>Unique instruments</small><strong>${r.unique_requested_instruments}</strong></div><div class="metric"><small>Verified by Kite</small><strong>${r.verified_kite_instruments}</strong></div><div class="metric"><small>Duplicate memberships</small><strong>${r.duplicate_membership_count}</strong></div></div><p class="subtle-note">${esc(r.note)}</p>${table(rows.filter(i=>i.resolution_kind!=='exact'))}<details><summary>Inspect all ${rows.length} configured instruments</summary>${table(rows)}</details>`;}catch(e){if($('reconciliationContent'))$('reconciliationContent').innerHTML=`<p class="notice error">${esc(e.message)}</p>`;}}
async function loadImports(){if(!$('importJobs'))return;try{const s=await api('/api/history/imports');const allowed=s.retention_authorized&&s.historical_enabled;document.querySelectorAll('[data-action="import"],[data-action="incremental"]').forEach(b=>b.disabled=!allowed);$('importNotice').textContent=allowed?'Authorized storage is enabled. Imports use verified tokens and a shared provider rate budget.':'Storage authorization required — DATA_RETENTION_AUTHORIZED remains false until you explicitly confirm permitted retention and ML use. No candles will be imported.';$('importSummary').innerHTML=`<div class="import-overview"><div class="metric"><small>Last successful import request</small><strong>${stamp(s.last_successful_import)}</strong></div><div class="metric"><small>Active jobs</small><strong>${s.active_jobs}</strong></div><div class="metric"><small>Automatic incremental updates</small><strong>${s.auto_update_enabled?'Enabled':'Disabled'}</strong></div></div>`;$('importJobs').innerHTML=s.jobs.length?`<div class="table-wrap"><table><thead><tr><th>Job</th><th>State / progress</th><th>Committed batches</th><th>Candles processed</th><th>Last success</th><th>Details</th><th>Controls</th></tr></thead><tbody>${s.jobs.map(j=>`<tr><td>${esc(j.id.slice(0,8))}<small>${esc(j.request.interval)} · ${j.incremental?'Incremental':'Backfill'}</small></td><td>${esc(j.state)}<small>${j.symbol_index}/${j.symbols.length||j.request.symbols.length} instruments complete</small><div class="job-progress" aria-hidden="true"><span style="width:${j.symbol_index/Math.max(1,j.symbols.length||j.request.symbols.length)*100}%"></span></div></td><td>${j.requests_completed}</td><td>${integer(j.candles_processed)}</td><td>${stamp(j.last_success_at)}</td><td><span class="import-request-note">${esc(j.error||`Cursor ${j.cursor_date||'next instrument'} · ${j.skipped.length} unavailable instrument(s) skipped`)}</span></td><td><div class="job-actions">${['failed','interrupted','blocked_authorization'].includes(j.state)?`<button class="secondary" data-import-control="resume" data-job-id="${esc(j.id)}" ${allowed?'':'disabled'}>Resume</button>`:''}${!['completed','cancelled'].includes(j.state)?`<button class="ghost" data-import-control="cancel" data-job-id="${esc(j.id)}">Cancel</button>`:''}</div></td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle-note">No historical import jobs have been started. The SQLite dataset contains no fabricated candles.</p>';}catch(e){if($('importJobs'))$('importJobs').innerHTML=`<p class="notice error">${esc(e.message)}</p>`;}}
document.addEventListener('click',event=>{const button=event.target.closest('[data-import-control]');if(button)action(button,async()=>{await api(`/api/history/imports/${encodeURIComponent(button.dataset.jobId)}/${button.dataset.importControl}`,{method:'POST'});await loadImports();});});
setInterval(()=>{if(location.pathname==='/history')loadImports();},5000);

initialize();

initializeAdminSession(notice);

$('mobileMore')?.addEventListener('click',()=>{const open=$('navigation').classList.toggle('open');$('mobileMore').setAttribute('aria-expanded',String(open));$('menuToggle').setAttribute('aria-expanded',String(open));});

window.addEventListener('divine-account-change',()=>{if(location.pathname==='/settings')mountPlatformSettings(notice);});
